spawnPoint() {
  const spawns = [...this.parts.values()].filter((p) => p.type === 'spawn');
  if (!spawns.length) return new THREE.Vector3(0, 6, 0);
  const s = spawns[Math.floor(Math.random() * spawns.length)];
  // scatter within the pad so players don't stack inside each other
  const ox = (Math.random() - 0.5) * Math.max(0, s.sx - 1.6);
  const oz = (Math.random() - 0.5) * Math.max(0, s.sz - 1.6);
  return new THREE.Vector3(s.x + ox, s.y + s.sy / 2 + 2.2, s.z + oz);
}
